const headers = $input.first().json.headers || {};
const body = $input.first().json.body;
const event = body.event || {};

// Ignore Slack retries
if (headers['x-slack-retry-num']) {
  return [];
}

// Ignore bot messages to prevent loops
if (event.bot_id || event.subtype === 'bot_message') {
  return [];
}

const eventType = event.type;
const isThreadReply = event.thread_ts && event.thread_ts !== event.ts;
const isReaction = eventType === 'reaction_added';

// Extract message text and remove bot mention
let text = (event.text || '').trim();
const textLower = text.toLowerCase().replace(/<@[A-Z0-9]+>/gi, '').trim();

// Determine event category
let category = 'unknown';
let command = null;

if (isReaction && event.reaction === 'white_check_mark') {
  category = 'resolve_decision';
} else if (isThreadReply) {
  category = 'thread_message';
} else if (textLower.includes('decisions') || textLower.includes('decisiones')) {
  category = 'command';
  command = 'decisions';
} else if (textLower.includes('help') || textLower.includes('ayuda')) {
  category = 'command';
  command = 'help';
}

return [{
  json: {
    category,
    command,
    channel: event.channel || event.item?.channel,
    user: event.user,
    text: text,
    thread_ts: event.thread_ts || event.ts,
    message_ts: event.ts,
    reaction: event.reaction,
    item_ts: event.item?.ts,
    event_type: eventType
  }
}];

const files = $input.all();
const mdFiles = files.filter(f => f.json.name && f.json.name.endsWith('.md'));

if (mdFiles.length === 0) {
  return [{ json: { files: [], hasFiles: false } }];
}

return mdFiles.map(f => ({ json: { path: f.json.path, name: f.json.name } }));

const items = $input.all();
const openDecisions = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let content;

  if (item.binary && item.binary.data) {
    try {
      const binaryData = await this.helpers.getBinaryDataBuffer(i, 'data');
      content = binaryData.toString('utf8');
    } catch (e) {
      continue;
    }
  } else {
    continue;
  }

  const fmMatch = content.match(/^---\n([\s\S]*?)\n---/);
  if (!fmMatch) continue;

  const lines = fmMatch[1].split('\n');
  const frontmatter = {};
  for (const line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex > 0) {
      const key = line.slice(0, colonIndex).trim();
      const value = line.slice(colonIndex + 1).trim().replace(/^["']|["']$/g, '');
      frontmatter[key] = value;
    }
  }

  if (frontmatter.status === 'open') {
    openDecisions.push({
      id: frontmatter.id || 'unknown',
      title: frontmatter.title || 'Sin título',
      created: frontmatter.created || '',
      path: item.json.path
    });
  }
}

return [{ json: { openDecisions, count: openDecisions.length } }];

const { openDecisions, count } = $input.first().json;
const channel = $('Parse Event').first().json.channel;

let text, blocks;

if (count === 0) {
  text = 'No hay decisiones abiertas';
  blocks = [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: '*No hay decisiones abiertas* :white_check_mark:'
      }
    }
  ];
} else {
  text = `Hay ${count} decisión(es) abierta(s)`;
  blocks = [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `Decisiones Abiertas (${count})`,
        emoji: true
      }
    }
  ];

  for (const decision of openDecisions) {
    blocks.push({
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*${decision.id}*: ${decision.title}`
      },
      accessory: {
        type: 'button',
        text: {
          type: 'plain_text',
          text: 'Ver detalle',
          emoji: true
        },
        value: JSON.stringify({ id: decision.id, path: decision.path, title: decision.title }),
        action_id: `view_decision_${decision.id}`
      }
    });
  }
}

return [{ json: { channel, text, blocks } }];

const channel = $('Parse Event').first().json.channel;

const text = 'Comandos disponibles';
const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: 'Akne - Ayuda',
      emoji: true
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Comandos disponibles:*'
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '• `decisions` o `decisiones` - Lista las decisiones de negocio abiertas'
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '• `help` o `ayuda` - Muestra este mensaje de ayuda'
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '• Responde en el hilo de una decisión para discutirla conmigo'
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '• Pon :white_check_mark: en un hilo para cerrar la decisión'
    }
  },
  {
    type: 'divider'
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: 'Puedes mencionarme en cualquier canal o enviarme un mensaje directo'
      }
    ]
  }
];

return [{ json: { channel, text, blocks } }];

// Slack sends interaction payload as form-urlencoded with 'payload' field
const body = $input.first().json.body;
let payload;

if (typeof body === 'string') {
  payload = JSON.parse(body);
} else if (body.payload) {
  payload = JSON.parse(body.payload);
} else {
  payload = body;
}

const action = payload.actions && payload.actions[0];
if (!action) {
  return [];
}

const actionId = action.action_id || '';
const value = action.value ? JSON.parse(action.value) : {};

return [{
  json: {
    action_id: actionId,
    decision_id: value.id,
    decision_path: value.path,
    decision_title: value.title,
    channel: payload.channel?.id || payload.container?.channel_id,
    user: payload.user?.id,
    message_ts: payload.message?.ts,
    response_url: payload.response_url
  }
}];

const item = $input.first();
const interactionData = $('Parse Interaction').first().json;

let content;
if (item.binary && item.binary.data) {
  const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
  content = binaryData.toString('utf8');
} else {
  return [{ json: { error: 'No content' } }];
}

// Parse frontmatter
const fmMatch = content.match(/^---\n([\s\S]*?)\n---/);
const frontmatterRaw = fmMatch ? fmMatch[1] : '';
const bodyContent = fmMatch ? content.slice(fmMatch[0].length).trim() : content;

// Parse YAML
const lines = frontmatterRaw.split('\n');
const frontmatter = {};
for (const line of lines) {
  const colonIndex = line.indexOf(':');
  if (colonIndex > 0) {
    const key = line.slice(0, colonIndex).trim();
    const value = line.slice(colonIndex + 1).trim().replace(/^["']|["']$/g, '');
    frontmatter[key] = value;
  }
}

// Extract sections
function extractSection(name) {
  const regex = new RegExp(`## ${name}\\s*\\n([\\s\\S]*?)(?=\\n## |$)`, 'i');
  const match = bodyContent.match(regex);
  return match ? match[1].trim() : '';
}

const context = extractSection('Contexto') || extractSection('Context');
const options = extractSection('Opciones') || extractSection('Options');
const question = extractSection('Pregunta') || extractSection('Question');

const githubUrl = `https://github.com/elevenyellow/akne/blob/main/${interactionData.decision_path}`;

return [{
  json: {
    channel: interactionData.channel,
    decision_id: interactionData.decision_id,
    decision_path: interactionData.decision_path,
    title: frontmatter.title || interactionData.decision_title,
    status: frontmatter.status,
    resolver: frontmatter.resolver,
    context,
    options,
    question,
    full_content: content,
    github_url: githubUrl,
    message_ts: interactionData.message_ts
  }
}];

const data = $('Parse Decision Detail').first().json;

// Truncate long text for Slack limits
const truncate = (text, max = 2500) => {
  if (!text) return '_No especificado_';
  if (text.length <= max) return text;
  return text.slice(0, max) + '...';
};

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `${data.decision_id}: ${data.title}`,
      emoji: true
    }
  },
  {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `*Estado:* ${data.status || 'open'}`
      },
      {
        type: 'mrkdwn', 
        text: `*Resolver:* ${data.resolver || 'No asignado'}`
      }
    ]
  },
  {
    type: 'divider'
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Contexto*\n${truncate(data.context)}`
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Opciones*\n${truncate(data.options)}`
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Pregunta*\n${truncate(data.question)}`
    }
  },
  {
    type: 'divider'
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `<${data.github_url}|Ver en GitHub> | Responde en este hilo para discutir | :white_check_mark: para cerrar`
      }
    ]
  }
];

// No thread_ts - cada detalle es un mensaje nuevo que inicia su propio thread
return [{
  json: {
    channel: data.channel,
    text: `Detalle de ${data.decision_id}: ${data.title}`,
    blocks
  }
}];

const decisionData = $('Lookup Thread Decision').first().json;
const threadData = $input.first().json;
const eventData = $('Parse Event').first().json;

const messages = threadData.messages || [];

// Build conversation history for Claude
const conversationHistory = messages
  .filter(m => !m.bot_id) // Exclude bot messages from history to Claude
  .map(m => ({
    role: 'user',
    content: m.text
  }));

// Get the latest user message
const latestMessage = eventData.text;

return [{
  json: {
    decision_id: decisionData.decision_id,
    decision_context: decisionData.decision_context,
    file_path: decisionData.file_path,
    channel: eventData.channel,
    thread_ts: eventData.thread_ts,
    user: eventData.user,
    latest_message: latestMessage,
    conversation_history: conversationHistory
  }
}];
